        /// The bridge's `switches [text]`: each switch (or those whose path or note has the text) with its value now.
        internal static string Status(string filter)
        {
            var sb = new StringBuilder("{\"count\":"); var rows = new List<string>();
            foreach (var s in All)
            {
                if (!string.IsNullOrEmpty(filter) && s.Path.IndexOf(filter, StringComparison.OrdinalIgnoreCase) < 0 && s.Other.IndexOf(filter, StringComparison.OrdinalIgnoreCase) < 0) continue;
                string value;
                try
                {
                    string path = Reflect.MemberPath(s.Path);
                    int dot = path.LastIndexOf('.');
                    var t = Reflect.FindType(path.Substring(0, dot));
                    var f = t?.GetField(path.Substring(dot + 1), BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
                    value = f == null ? "(missing)" : Convert.ToString(f.GetValue(null), System.Globalization.CultureInfo.InvariantCulture);
                }
                catch (Exception e) { value = "(" + e.GetType().Name + ")"; }
                rows.Add("{\"path\":" + Json.Str(s.Path) + ",\"kind\":" + Json.Str(s.Kind.ToString()) + ",\"value\":" + Json.Str(value) + ",\"other\":" + Json.Str(s.Other) + "}");
            }
            return sb.Append(rows.Count).Append(",\"switches\":[").Append(string.Join(",", rows)).Append("]}").ToString();
        }
    }
